#!/usr/bin/env bash
set -eu
usage(){ echo "Usage: $0 [-v] [-o output] [files...]"; }
VERBOSE=''
OUTPUT=''
while getopts "vo:" opt; do
  case $opt in
    v) VERBOSE=1;;
    o) OUTPUT=$OPTARG;;
    \?) usage; exit 2;;
  esac
done
shift $((OPTIND-1))
args=("$@")
printf 'verbose=%s output=%s args_count=%d\n' "$VERBOSE" "$OUTPUT" "${#args[@]}"
if [ "$#" -gt 0 ]; then printf 'first_arg=%s\n' "$1"; fi
